"""World model for sb26.

Screen layout:
  rows 0-7            : target strip - hollow squares giving a colour ORDER
  rows 8 .. bar-1     : play area - one or more panels holding 2x2 slots
                        (colour 2). A panel may contain a hollow "door"
                        square wired by a 2-wide pipe to a nested panel;
                        the door's position in the reading order is where
                        the nested panel's slots get spliced in.
  row  ~53            : bar, colour 2, consumed from the right with 3
  rows bar+1 .. 63    : palette - 4x4 colour blocks

Interactions (all confirmed by backtest):
  click a palette block  : selects it (0 ring). FREE, no bar tick.
  click a 2x2 slot       : places the selected colour as a 4x4 block on the
                           slot (slot rect grown by 1); the palette block
                           shrinks to a 2x2 slot marker; selection clears.
                           Costs one bar tick.
  action 7               : undo the most recent placement. FREE.
  action 5               : SUBMIT. Costs one tick. If every slot is filled
                           and the arrangement matches the target order the
                           level advances; otherwise nothing visible happens.
"""

BG = 4
SEL = 0
SLOT = 2


def _bar_row(g):
    for r in range(len(g)):
        if set(g[r]) <= {2, 3} and len(g[r]) == 64:
            return r
    return None


def _mid_rows(g):
    br = _bar_row(g)
    return range(8, br if br is not None else 53)


def _pal_rows(g):
    br = _bar_row(g)
    return range((br + 1) if br is not None else 54, len(g))


def _boxes(g, rows):
    """Solid same-colour rectangles inside `rows` (bg/ring colours aside)."""
    rows = list(rows)
    rowset = set(rows)
    cols = range(len(g[0]))
    seen = set()
    out = []
    for r in rows:
        for c in cols:
            v = g[r][c]
            if (r, c) in seen or v in (BG, SEL):
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = rr + dr, cc + dc
                    if (nr in rowset and 0 <= nc < len(g[0])
                            and (nr, nc) not in seen and g[nr][nc] == v):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0 = min(p[0] for p in comp)
            r1 = max(p[0] for p in comp)
            c0 = min(p[1] for p in comp)
            c1 = max(p[1] for p in comp)
            h, w = r1 - r0 + 1, c1 - c0 + 1
            if len(comp) == h * w:
                out.append((v, r0, r1, c0, c1, False))
            elif h > 2 and w > 2 and len(comp) == 2 * h + 2 * w - 4 and all(
                    g[rr][cc] == v for rr in (r0, r1) for cc in range(c0, c1 + 1)
            ) and all(g[rr][cc] == v for cc in (c0, c1)
                      for rr in range(r0, r1 + 1)):
                out.append((v, r0, r1, c0, c1, True))  # hollow: a door
    return out


def _slots(g):
    return [b for b in _boxes(g, _mid_rows(g))
            if b[0] == SLOT and not b[5] and b[2] - b[1] == 1
            and b[4] - b[3] == 1]


def _selected(g):
    rows = _pal_rows(g)
    for v, r0, r1, c0, c1, hollow in _boxes(g, rows):
        if v == SLOT:
            continue
        if r0 - 1 >= 0 and c0 - 1 >= 0 and g[r0 - 1][c0 - 1] == SEL:
            return (v, r0, r1, c0, c1, hollow)
    return None


def _fill(g, r0, r1, c0, c1, v):
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            g[r][c] = v


def _ring(g, r0, r1, c0, c1, v):
    for c in range(c0 - 1, c1 + 2):
        g[r0 - 1][c] = v
        g[r1 + 1][c] = v
    for r in range(r0, r1 + 1):
        g[r][c0 - 1] = v
        g[r][c1 + 1] = v


def _tick(g):
    br = _bar_row(g)
    if br is None:
        return
    for c in range(len(g[br]) - 1, -1, -1):
        if g[br][c] == 2:
            g[br][c] = 3
            return








LAST_LEVEL = 7  # levels 0..7; clearing level 7 is the WIN

ENTRY_GRIDS = {
    1: '',
    2: '',
    3: '',
    4: '',
    5: '',
    6: '',
    7: '',
}


def _decode(s):
    return [[int(s[r * 64 + c], 16) for c in range(64)] for r in range(64)]

def init_state(entry_grid):
    return {"stack": []}


def predict(state, grid, action, x=None, y=None):
    g = [row[:] for row in grid]
    st = {"stack": [list(e) for e in state.get("stack", [])]}
    info = {}

    if action == 5:  # submit
        _tick(g)
        if not _slots(grid):
            info["level_up"] = True
            if CURRENT_LEVEL >= LAST_LEVEL:  # noqa: F821
                info["win"] = True
            nxt = ENTRY_GRIDS.get(CURRENT_LEVEL + 1)  # noqa: F821
            if nxt:
                g = _decode(nxt)
        return g, info, st

    if action == 7:  # undo last placement (free)
        if st["stack"]:
            colour, slot, pal = st["stack"].pop()
            _fill(g, slot[0], slot[1], slot[2], slot[3], BG)
            _fill(g, slot[0] + 1, slot[1] - 1, slot[2] + 1, slot[3] - 1, SLOT)
            _fill(g, pal[0], pal[1], pal[2], pal[3], colour)
        return g, info, st

    if action != 6:
        return g, info, st

    if y in _pal_rows(grid):  # select a palette block (free)
        for v, r0, r1, c0, c1, hollow in _boxes(grid, _pal_rows(grid)):
            if v != SLOT and r0 <= y <= r1 and c0 <= x <= c1:
                sel = _selected(grid)
                if sel:
                    _ring(g, sel[1], sel[2], sel[3], sel[4], BG)
                _ring(g, r0, r1, c0, c1, SEL)
                break
        return g, info, st

    sel = _selected(grid)
    for v, r0, r1, c0, c1, _h in _slots(grid):
        if r0 <= y <= r1 and c0 <= x <= c1:
            if sel is None:
                return g, info, st
            _fill(g, r0 - 1, r1 + 1, c0 - 1, c1 + 1, sel[0])
            if sel[5]:  # a door: only its outline is drawn
                _fill(g, r0, r1, c0, c1, BG)
            _ring(g, sel[1], sel[2], sel[3], sel[4], BG)
            _fill(g, sel[1], sel[2], sel[3], sel[4], BG)
            _fill(g, sel[1] + 1, sel[2] - 1, sel[3] + 1, sel[4] - 1, SLOT)
            _tick(g)
            st["stack"].append([sel[0], [r0 - 1, r1 + 1, c0 - 1, c1 + 1],
                                [sel[1], sel[2], sel[3], sel[4]]])
            break
    return g, info, st
